import math

def calculate_ratio(x, y, z):
    numerator = (2*x**2 + 1) * (2*y**2 + 1) * (2*z**2 + 1)
    denominator = x*y + y*z + z*x
    if denominator == 0:
        return float('inf')
    return numerator / denominator

# Test case based on observation from previous run
test_points = [
    (3, 3, 3),
    (4, 4, 4),
    (1, 2, 3) # Recheck for comparison
]

ratios = {}
max_ratio = -float('inf')

print("--- Testing Further Ratios ---")
for x, y, z in test_points:
    R = calculate_ratio(x, y, z)
    ratios[(x, y, z)] = R
    if R > max_ratio:
        max_ratio = R
    print(f"R({x}, {y}, {z}) = {R}")

print("\nMaximum observed ratio in this batch: " + str(max_ratio))

